package com.mycompany.greenbasket;
import java.io.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;
@WebServlet("/UpdateUserServlet") public class UpdateUserServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{UserReg u=new UserReg();u.setId(Integer.parseInt(r.getParameter("id")));u.setName(r.getParameter("name"));u.setEmail(r.getParameter("email"));u.setPassword(r.getParameter("password"));u.setMob(r.getParameter("mob"));u.setGender(r.getParameter("gender"));u.setAdd(r.getParameter("add"));u.setCity(r.getParameter("city"));u.setState(r.getParameter("state"));if(new UserRegDAO().updateUser(u)){r.getSession().setAttribute("loggedUser",u);s.sendRedirect(r.getContextPath()+"/welcomeUser.jsp");}else s.sendError(400,"Update failed");}catch(Exception e){s.sendError(400,"Invalid user information");}}}
